     1	package br.com.marealta.reservas.reports;
     2	
     3	import br.com.marealta.reservas.domain.ReservationService;
     4	
     5	import java.util.List;
     6	import java.util.stream.Collectors;
     7	
     8	/** Único lugar que define o jeito dos relatórios CSV: título, cabeçalho, linhas, total. */
     9	public class CsvReportWriter {
    10	    public String write(ReportTable table) {
    11	        StringBuilder sb = new StringBuilder();
    12	        line(sb, List.of(ReservationService.INN_NAME, table.name(), table.period()));
    13	        line(sb, table.header());
    14	        table.rows().forEach(row -> line(sb, row));
    15	        line(sb, table.total());
    16	        return sb.toString();
    17	    }
    18	
    19	    private static void line(StringBuilder sb, List<String> cells) {
    20	        sb.append(cells.stream().map(CsvReportWriter::escape).collect(Collectors.joining(","))).append('\n');
    21	    }
    22	
    23	    private static String escape(String cell) {
    24	        if (cell.contains(",") || cell.contains("\"") || cell.contains("\n") || cell.contains("\r")) {
    25	            return '"' + cell.replace("\"", "\"\"") + '"';
    26	        }
    27	        return cell;
    28	    }
    29	}
