     7	import java.util.Comparator;
     8	import java.util.List;
     9	
    10	public class OccupancyReport implements Report {
    11	    private final ReservationService service;
    12	
    13	    public OccupancyReport(ReservationService service) {
    14	        this.service = service;
    15	    }
    16	
    17	    @Override
    18	    public String name() {
    19	        return "occupancy";
    20	    }
    21	
    22	    @Override
    23	    public String periodParam() {
    24	        return "date";
    25	    }
    26	
    27	    @Override
    28	    public ReportTable build(String period) {
    29	        LocalDate date = Periods.date(period);
    30	        List<Reservation> occupying = service.all().stream()
    31	                .filter(r -> r.status().isPaid() && r.occupiesNight(date))
    32	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()).thenComparingInt(Reservation::id))
    33	                .toList();
    34	        List<List<String>> rows = occupying.stream().map(r -> List.of(
    35	                String.valueOf(r.room().number()), r.room().type().name(), String.valueOf(r.id()),
    36	                r.checkIn().toString(), r.checkOut().toString())).toList();
    37	        long occupiedRooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    38	        return new ReportTable(name(), date.toString(),
    39	                List.of("room", "type", "reservation", "check_in", "check_out"), rows,
    40	                List.of("total", occupiedRooms + "/" + service.rooms().size()));
    41	    }
