     1	package br.com.marealta.reservas.reports;
     2	
     3	import br.com.marealta.reservas.domain.BookingException;
     4	import br.com.marealta.reservas.domain.ErrorCode;
     5	
     6	import java.time.LocalDate;
     7	import java.time.YearMonth;
     8	import java.time.format.DateTimeParseException;
     9	
    10	final class Periods {
    11	    private Periods() {
    12	    }
    13	
    14	    static LocalDate date(String raw) {
    15	        try {
    16	            return LocalDate.parse(required(raw, "date"));
    17	        } catch (DateTimeParseException e) {
    18	            throw new BookingException(ErrorCode.INVALID_REQUEST, "date deve estar no formato AAAA-MM-DD");
    19	        }
    20	    }
    21	
    22	    static YearMonth month(String raw) {
    23	        String value = required(raw, "month");
    24	        if (!value.matches("\\d{4}-\\d{2}")) {
    25	            throw new BookingException(ErrorCode.INVALID_REQUEST, "month deve estar no formato AAAA-MM");
    26	        }
    27	        try {
    28	            return YearMonth.parse(value);
    29	        } catch (DateTimeParseException e) {
    30	            throw new BookingException(ErrorCode.INVALID_REQUEST, "month deve estar no formato AAAA-MM");
    31	        }
    32	    }
    33	
    34	    private static String required(String raw, String name) {
    35	        if (raw == null || raw.isBlank()) {
    36	            throw new BookingException(ErrorCode.INVALID_REQUEST, "Parâmetro " + name + " é obrigatório");
    37	        }
    38	        return raw;
    39	    }
    40	}
