     8	import java.math.BigDecimal;
     9	import java.time.YearMonth;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	
    13	public class RatePlanReport implements Report {
    14	    private final ReservationService service;
    15	
    16	    public RatePlanReport(ReservationService service) {
    17	        this.service = service;
    18	    }
    19	
    20	    @Override
    21	    public String name() {
    22	        return "rate-plans";
    23	    }
    24	
    25	    @Override
    26	    public String periodParam() {
    27	        return "month";
    28	    }
    29	
    30	    @Override
    31	    public ReportTable build(String period) {
    32	        YearMonth month = Periods.month(period);
    33	        List<Reservation> kept = ReservationQueries.keptMoneyStartingIn(service, month);
    34	        List<List<String>> rows = new ArrayList<>();
    35	        int totalCount = 0;
    36	        BigDecimal totalAmount = Money.ZERO;
    37	        for (RatePlan plan : RatePlan.values()) {
    38	            List<Reservation> ofPlan = kept.stream().filter(r -> r.ratePlan() == plan).toList();
    39	            BigDecimal amount = ofPlan.stream().map(Reservation::amountKept).reduce(Money.ZERO, BigDecimal::add);
    40	            rows.add(List.of(plan.name(), String.valueOf(ofPlan.size()), Money.plain(amount)));
    41	            totalCount += ofPlan.size();
    42	            totalAmount = totalAmount.add(amount);
    43	        }
    44	        return new ReportTable(name(), month.toString(), List.of("rate_plan", "reservations", "amount"), rows,
    45	                List.of("total", String.valueOf(totalCount), Money.plain(totalAmount)));
    46	    }
    47	}
