     1	package br.com.marealta.reservas.reports;
     2	
     3	import br.com.marealta.reservas.domain.Reservation;
     4	import br.com.marealta.reservas.domain.ReservationService;
     5	
     6	import java.time.YearMonth;
     7	import java.util.Comparator;
     8	import java.util.List;
     9	
    10	/** Seleções de reservas compartilhadas entre relatórios, para que usem sempre o mesmo critério. */
    11	final class ReservationQueries {
    12	    static final Comparator<Reservation> BY_CHECK_IN_THEN_ID =
    13	            Comparator.comparing(Reservation::checkIn).thenComparingInt(Reservation::id);
    14	
    15	    private ReservationQueries() {
    16	    }
    17	
    18	    /** Reservas pagas (confirmadas, com check-in ou check-out) que começam no mês. */
    19	    static List<Reservation> paidStartingIn(ReservationService service, YearMonth month) {
    20	        return startingIn(service, month).stream().filter(r -> r.status().isPaid()).toList();
    21	    }
    22	
    23	    /** Reservas que começam no mês e deixaram dinheiro com a pousada. */
    24	    static List<Reservation> keptMoneyStartingIn(ReservationService service, YearMonth month) {
    25	        return startingIn(service, month).stream().filter(r -> r.amountKept().signum() > 0).toList();
    26	    }
    27	
    28	    private static List<Reservation> startingIn(ReservationService service, YearMonth month) {
    29	        return service.all().stream()
    30	                .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    31	                .sorted(BY_CHECK_IN_THEN_ID)
    32	                .toList();
    33	    }
    34	}
