     3	import br.com.marealta.reservas.domain.Money;
     4	import br.com.marealta.reservas.domain.Reservation;
     5	import br.com.marealta.reservas.domain.ReservationService;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.YearMonth;
     9	import java.util.List;
    10	
    11	public class TourismTaxReport implements Report {
    12	    private final ReservationService service;
    13	    private final BigDecimal taxPerGuestNight;
    14	
    15	    public TourismTaxReport(ReservationService service, BigDecimal taxPerGuestNight) {
    16	        this.service = service;
    17	        this.taxPerGuestNight = taxPerGuestNight;
    18	    }
    19	
    20	    @Override
    21	    public String name() {
    22	        return "tourism-tax";
    23	    }
    24	
    25	    @Override
    26	    public String periodParam() {
    27	        return "month";
    28	    }
    29	
    30	    private BigDecimal tax(Reservation r) {
    31	        return Money.round(taxPerGuestNight.multiply(BigDecimal.valueOf((long) r.guests() * r.nights())));
    32	    }
    33	
    34	    @Override
    35	    public ReportTable build(String period) {
    36	        YearMonth month = Periods.month(period);
    37	        List<Reservation> paid = ReservationQueries.paidStartingIn(service, month);
    38	        List<List<String>> rows = paid.stream().map(r -> List.of(
    39	                String.valueOf(r.id()), String.valueOf(r.room().number()),
    40	                r.checkIn().toString(), r.checkOut().toString(),
    41	                String.valueOf(r.guests()), String.valueOf(r.nights()),
    42	                Money.plain(tax(r)))).toList();
    43	        BigDecimal total = paid.stream().map(this::tax).reduce(Money.ZERO, BigDecimal::add);
    44	        return new ReportTable(name(), month.toString(),
    45	                List.of("reservation", "room", "check_in", "check_out", "guests", "nights", "tax"), rows,
    46	                List.of("total", Money.plain(total)));
    47	    }
    48	}

