    26	public final class App {
    27	    public static final BigDecimal DEFAULT_TOURISM_TAX = new BigDecimal("4.50");
    28	
    29	    private final ObjectMapper mapper = new ObjectMapper().enable(SerializationFeature.WRITE_BIGDECIMAL_AS_PLAIN);
    30	    private final RequestParser parser = new RequestParser(mapper);
    31	    private final CsvReportWriter csv = new CsvReportWriter();
    32	    private final MessageLog messages = new MessageLog();
    33	    private final ReservationService service = new ReservationService(RoomCatalog.standard(), messages);
    34	    private final List<Report> reports;
    35	
    36	    public App(BigDecimal tourismTaxPerGuestNight) {
    37	        this.reports = List.of(
    38	                new OccupancyReport(service),
    39	                new RevenueReport(service),
    40	                new TourismTaxReport(service, tourismTaxPerGuestNight),
    41	                new RatePlanReport(service));
    42	    }
    43	
    44	    public Javalin create() {
    45	        Javalin app = Javalin.create();
    46	        app.exception(BookingException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    47	
    48	        app.get("/rooms", ctx -> json(ctx, 200, service.rooms().all().stream().map(Json::room).toList()));
    49	        app.post("/reservations", ctx -> json(ctx, 201,
    50	                Json.reservation(service.create(parser.parseNewReservation(ctx.body())))));
    51	        app.get("/reservations/{id}", ctx -> json(ctx, 200, Json.reservation(service.get(id(ctx)))));
    52	        transition(app, "confirmation", service::confirm);
    53	        transition(app, "cancellation", service::cancel);
    54	        transition(app, "check-in", service::checkIn);
    55	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, Json.receipt(service.checkOut(id(ctx)))));
    56	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, Json.receipt(service.document(id(ctx)))));
    57	        app.get("/messages", ctx -> json(ctx, 200, messages.all().stream().map(Json::message).toList()));
    58	
    59	        for (Report report : reports) {
    60	            app.get("/reports/" + report.name(), ctx -> ctx
    61	                    .contentType("text/csv; charset=utf-8")
    62	                    .result(csv.write(report.build(ctx.queryParam(report.periodParam())))));
    63	        }
    64	        return app;
    65	    }
    66	
    67	    private void transition(Javalin app, String path, Function<Integer, Reservation> action) {
    68	        app.post("/reservations/{id}/" + path, ctx -> json(ctx, 200, Json.reservation(action.apply(id(ctx)))));
    69	    }
    70	
    71	    private static int id(Context ctx) {
    72	        try {
    73	            return Integer.parseInt(ctx.pathParam("id"));
    74	        } catch (NumberFormatException e) {
    75	            throw new BookingException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não existe");
    76	        }
    77	    }
    78	
    79	    private void json(Context ctx, int status, Object body) throws Exception {
    80	        ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
    81	    }
    82	
    83	    private void error(Context ctx, ErrorCode code, String message) {
    84	        Map<String, Object> body = new LinkedHashMap<>();
    85	        body.put("error", code.name());
    86	        body.put("message", message);
    87	        try {
    88	            json(ctx, code.httpStatus(), body);
    89	        } catch (Exception e) {
    90	            ctx.status(500);
    91	        }
    92	    }
    93	}
